ini_set('display_errors','0');header('Content-Type: application/json; charset=utf-8');header('Cache-Control: no-store');require __DIR__.'/../lib/Db.php';require __DIR__.'/../lib/Jwt.php';$C=require __DIR__.'/../config.php';
